"use client";

/**
 * Word rotate: a sentence with one slot that cycles through words. The words
 * slide, flip over, spin past on a reel, or land beside a box that ticks.
 * The slot resizes to each word, so the sentence never leaves a gap.
 *
 * Written by Better Design. Painted from the theme prop, so the sentence takes
 * the product's ink and the cycling word takes its primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { type CSSProperties, type ReactNode, useEffect, useRef, useState } from "react";
import { AbsoluteFill, continueRender, delayRender, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, progress, springs, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER, waitUntilDone } = loadFont("normal", { weights: ["700"], subsets: ["latin"] });

/** How the slot changes words. */
export type WordRotateVariant = "slide" | "flip" | "wheel" | "check";

export interface WordRotateProps {
  /** Words before the slot. */
  prefix?: string;
  /** The words the slot cycles through. The last one stays. */
  words?: string[];
  /** Words after the slot, punctuation included. */
  suffix?: string;
  /** `slide` rises, `flip` turns on its axis, `wheel` spins a reel, `check` ticks a box per word. */
  variant?: WordRotateVariant;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const SIZE = 112;
const FIRST = 10;
const STEP = 26;
const SWAP = 12;
const SPIN_AT = 12;
const SPIN_FRAMES = 66;

/** A sentence whose one slot cycles through words. */
export function WordRotate({
  prefix = "Make a film for every",
  words = ["launch", "feature", "update", "release"],
  suffix = "",
  variant = "slide",
  theme: themeOverride,
  font,
}: WordRotateProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);
  const list = words.length > 0 ? words : [""];
  const n = list.length;

  const key = list.join("|");
  const refs = useRef<(HTMLSpanElement | null)[]>([]);
  const [handle] = useState(() => delayRender("Measure the rotating words"));
  const [widths, setWidths] = useState<number[]>([]);
  useEffect(() => {
    Promise.all([waitUntilDone(), document.fonts.ready]).then(() => {
      setWidths(list.map((_, i) => refs.current[i]?.offsetWidth ?? 0));
      continueRender(handle);
    });
  }, [handle, family, key]);
  const w = (i: number) => widths[Math.max(0, Math.min(n - 1, i))] ?? 0;

  const enter = easings.out(progress(frame, 0, 18));
  // Which word is current, and how far the swap into it has gone.
  const landed = Math.max(0, Math.min(n - 1, Math.floor((frame - FIRST) / STEP)));
  const next = Math.min(n - 1, landed + 1);
  const swapStart = FIRST + next * STEP - SWAP;
  const swap = next === landed ? 0 : easings.inOut(progress(frame, swapStart, SWAP));
  const cur = swap >= 1 ? next : landed;

  let slotWidth = interpolate(swap, [0, 1], [w(landed), w(next)]);
  let slot: ReactNode;
  const word = (i: number, style: CSSProperties, k: number = i) => (
    <span key={k} style={{ position: "absolute", left: 0, right: 0, top: 0, textAlign: "center", whiteSpace: "nowrap", ...style }}>
      {list[i]}
    </span>
  );

  if (variant === "wheel") {
    const reel = 2 * n + (n - 1);
    const rest = progress(frame, SPIN_AT + SPIN_FRAMES - 6, 14);
    const pos = easings.overshoot(progress(frame, SPIN_AT, SPIN_FRAMES)) * reel;
    const widest = Math.max(...list.map((_, i) => w(i)));
    slotWidth = interpolate(progress(frame, SPIN_AT + SPIN_FRAMES - 14, 14), [0, 1], [widest, w(n - 1)]);
    const items = [];
    for (let i = Math.floor(pos) - 2; i <= Math.ceil(pos) + 2; i++) {
      if (i < 0 || i > reel) continue;
      const d = i - pos;
      items.push(
        word(i % n, {
          top: "1.1em",
          transform: `translateY(${d * 1.05}em) rotateX(${-d * 28}deg)`,
          opacity: Math.max(0, 1 - Math.abs(d) * 0.72) * (Math.abs(d) > 0.5 ? 1 - rest : 1),
        }, i),
      );
    }
    slot = items;
  } else if (variant === "flip") {
    slot = [
      swap < 0.5 ? word(landed, { transform: `rotateX(${swap * 180}deg)`, transformOrigin: "50% 50% -0.4em", opacity: 1 - swap * 1.4 }) : null,
      swap >= 0.5 && next !== landed ? word(next, { transform: `rotateX(${(swap - 1) * 180}deg)`, transformOrigin: "50% 50% -0.4em", opacity: (swap - 0.3) * 1.4 }) : null,
    ];
  } else {
    slot = [
      swap < 1 ? word(landed, { transform: `translateY(${-swap * 0.9}em)`, opacity: 1 - swap, filter: `blur(${swap * 8}px)` }) : null,
      next !== landed && swap > 0 ? word(next, { transform: `translateY(${(1 - swap) * 0.9}em)`, opacity: swap, filter: `blur(${(1 - swap) * 8}px)` }) : null,
    ];
  }

  // The box ticks when a word lands and clears just before the next one swaps in.
  const landAt = FIRST + cur * STEP;
  const tick = spring({ frame: frame - (variant === "check" ? landAt : 0), fps, config: springs.bouncy });
  const clearing = cur < n - 1 ? progress(frame, FIRST + (cur + 1) * STEP - SWAP - 4, 4) : 0;
  const ticked = Math.max(0, Math.min(1, tick)) * (1 - clearing);
  const box = SIZE * 0.68;

  return (
    <AbsoluteFill style={{ background: theme.background, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div style={{ position: "absolute", visibility: "hidden", fontSize: SIZE, fontWeight: 700, letterSpacing: "-0.035em" }}>
        {list.map((item, i) => (
          <span key={i} ref={(el) => { refs.current[i] = el; }} style={{ position: "absolute", whiteSpace: "nowrap" }}>
            {item}
          </span>
        ))}
      </div>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "0.26em",
          fontSize: SIZE,
          fontWeight: 700,
          letterSpacing: "-0.035em",
          lineHeight: 1.2,
          color: theme.foreground,
          whiteSpace: "nowrap",
          opacity: enter,
          transform: `translateY(${(1 - enter) * 24}px)`,
        }}
      >
        <span>{prefix}</span>
        {variant === "check" ? (
          <span
            style={{
              width: box,
              height: box,
              flexShrink: 0,
              borderRadius: box * 0.24,
              border: `${Math.round(box * 0.07)}px solid ${ticked > 0.02 ? theme.primary : withAlpha(theme.mutedForeground, 0.55)}`,
              background: ticked > 0.02 ? theme.primary : theme.card,
              transform: `scale(${0.9 + 0.1 * Math.min(1.1, tick)})`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              marginLeft: "0.06em",
            }}
          >
            <svg width={box * 0.62} height={box * 0.62} viewBox="0 0 24 24">
              <path d="M4 12.5l5 5L20 6.5" fill="none" stroke={theme.primaryForeground} strokeWidth={3.4} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray="1 1" strokeDashoffset={1 - ticked} />
            </svg>
          </span>
        ) : null}
        <span
          style={{
            position: "relative",
            display: "inline-block",
            width: slotWidth,
            height: variant === "wheel" ? "3.4em" : "1.2em",
            margin: variant === "wheel" ? "-1.1em 0" : undefined,
            overflow: variant === "wheel" ? "visible" : "hidden",
            color: theme.primary,
            perspective: variant === "flip" || variant === "wheel" ? 900 : undefined,
            maskImage: variant === "wheel" ? "linear-gradient(transparent, black 34%, black 66%, transparent)" : undefined,
            WebkitMaskImage: variant === "wheel" ? "linear-gradient(transparent, black 34%, black 66%, transparent)" : undefined,
          }}
        >
          {slot}
        </span>
        {suffix ? <span style={{ marginLeft: /^\w/.test(suffix) ? 0 : "-0.26em" }}>{suffix}</span> : null}
      </div>
    </AbsoluteFill>
  );
}
